mapper.select:
SELECT d.DEPRECIATION_ID, d.ASSET_ID, d.PERIOD, d.DEPRECIATION_METHOD, d.MONTHLY_DEPRECIATION, d.ACCUMULATED_DEPRECIATION, d.NET_VALUE, d.VOUCHER_NO, d.STATUS, d.REMARK, d.TENANT_ID, d.CREATE_BY, d.CREATE_TIME, d.UPDATE_BY, d.UPDATE_TIME, d.IS_DELETED, a.ASSET_CODE AS assetCode, a.ASSET_NAME AS assetName FROM TBL_FIXED_ASSET_DEPRECIATION d LEFT JOIN TBL_FIXED_ASSET_CARD a ON d.ASSET_ID = a.ASSET_ID AND a.IS_DELETED = 0 WHERE d.IS_DELETED = 0
AND d.TENANT_ID = #{tenantId}
AND a.ASSET_CODE LIKE CONCAT('%', #{assetCode}, '%')
AND d.PERIOD >= #{startPeriod}
AND d.PERIOD <= #{endPeriod}
ORDER BY d.PERIOD DESC, d.CREATE_TIME DESC

SELECT d.DEPRECIATION_ID, d.ASSET_ID, d.PERIOD, d.DEPRECIATION_METHOD, d.MONTHLY_DEPRECIATION, d.ACCUMULATED_DEPRECIATION, d.NET_VALUE, d.VOUCHER_NO, d.STATUS, d.REMARK, d.TENANT_ID, d.CREATE_BY, d.CREATE_TIME, d.UPDATE_BY, d.UPDATE_TIME, d.IS_DELETED, a.ASSET_CODE AS assetCode, a.ASSET_NAME AS assetName FROM TBL_FIXED_ASSET_DEPRECIATION d LEFT JOIN TBL_FIXED_ASSET_CARD a ON d.ASSET_ID = a.ASSET_ID AND a.IS_DELETED = 0 WHERE d.PERIOD = #{period} AND d.IS_DELETED = 0
AND d.TENANT_ID = #{tenantId}
ORDER BY a.ASSET_CODE ASC

SELECT NVL(SUM(d.MONTHLY_DEPRECIATION), 0) AS totalAmount, NVL(SUM(d.ACCUMULATED_DEPRECIATION), 0) AS accumulatedAmount, COUNT(DISTINCT d.ASSET_ID) AS assetCount, CASE WHEN SUM(a.ORIGINAL_VALUE) > 0 THEN ROUND(SUM(d.ACCUMULATED_DEPRECIATION) / SUM(a.ORIGINAL_VALUE) * 100, 2) ELSE 0 END AS depreciationRate FROM TBL_FIXED_ASSET_DEPRECIATION d LEFT JOIN TBL_FIXED_ASSET_CARD a ON d.ASSET_ID = a.ASSET_ID AND a.IS_DELETED = 0 WHERE d.IS_DELETED = 0
AND d.TENANT_ID = #{tenantId}
AND d.PERIOD >= #{startPeriod}
AND d.PERIOD <= #{endPeriod}
AND a.CATEGORY_ID = #{categoryId}

SELECT d.PERIOD AS period, NVL(SUM(d.MONTHLY_DEPRECIATION), 0) AS amount, COUNT(DISTINCT d.ASSET_ID) AS assetCount FROM TBL_FIXED_ASSET_DEPRECIATION d WHERE d.IS_DELETED = 0
AND d.TENANT_ID = #{tenantId}
AND d.PERIOD >= #{startPeriod}
AND d.PERIOD <= #{endPeriod}
GROUP BY d.PERIOD ORDER BY d.PERIOD ASC

SELECT COUNT(*)
FROM TBL_FIXED_ASSET_DEPRECIATION
WHERE ASSET_ID = #{assetId}
  AND PERIOD = #{period}
  AND IS_DELETED = 0

    AND TENANT_ID = #{tenantId}
